&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul data-path-to-node=&quot;22&quot;&gt;
&lt;li&gt;
&lt;p id=&quot;p-rc_dfacf76f4e173b9e-106&quot; data-path-to-node=&quot;22,0,0&quot;&gt;&lt;strong data-path-to-node=&quot;22,0,0&quot; data-index-in-node=&quot;0&quot;&gt;&lt;span class=&quot;citation-36 citation-37 citation-end-37&quot;&gt;Based in Colorado, Hawaii, Illinois, Maryland, Massachuse&lt;/span&gt;&lt;span class=&quot;citation-36 citation-end-36&quot;&gt;tts, Min&lt;/span&gt;nesota, Vermont or Washington D.C.:&lt;/strong&gt; $65,000 - $85,000&lt;/p&gt;
